/**
 * Whether a customer bought a product (or one of its variations) in the last $days days.
 *
 * @param int $user_id    Customer user ID.
 * @param int $product_id Product or variation ID.
 * @param int $days       Number of days to look back.
 * @return bool
 */
function perfectpixel_customer_bought_product_recently( $user_id, $product_id, $days = 365 ) {
	if ( ! $user_id || ! $product_id ) {
		return false;
	}
	$orders = wc_get_orders(
		array(
			'customer_id'  => (int) $user_id,
			'status'       => wc_get_is_paid_statuses(),
			'date_created' => '>' . ( time() - max( 1, (int) $days ) * DAY_IN_SECONDS ),
			'limit'        => -1,
		)
	);
	foreach ( $orders as $order ) {
		foreach ( $order->get_items() as $item ) {
			if ( (int) $item->get_product_id() === (int) $product_id || (int) $item->get_variation_id() === (int) $product_id ) {
				return true;
			}
		}
	}
	return false;
}
